// Verify against the exact bytes Convex signed, not a re-serialized copy:
// JSON.stringify(JSON.parse(x)) is not guaranteed to equal x.
const { headers } = $input.first().json;
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const id = headers['webhook-id'] ?? '';
const timestamp = headers['webhook-timestamp'] ?? '';
return [{
  json: { id, timestamp, signatures: headers['webhook-signature'] ?? '', raw, signedContent: `${id}.${timestamp}.${raw}` },
}];

// Standard Webhooks verification: a v1 signature must match and the timestamp
// must be within 5 minutes (replay window). The comparison is constant-time.
const { id, timestamp, signatures, expected, raw } = $input.first().json;
const now = Math.floor(Date.now() / 1000);
const fresh = /^\d{1,12}$/.test(timestamp) && Math.abs(now - Number(timestamp)) <= 300;
const same = (a, b) => {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};
const provided = String(signatures).split(' ').filter((s) => s.startsWith('v1,')).map((s) => s.slice(3));
const signed = fresh && provided.some((signature) => same(signature, expected));
let event = null;
if (signed) {
  try { event = JSON.parse(raw); } catch { event = null; }
}
const valid = Boolean(event && event.type === 'loan.status_changed' && event.eventId === id);
// Only the parsed event goes forward: no raw body, signatures or HMACs.
return [{
  json: { valid, reason: valid ? null : !fresh ? 'stale_timestamp' : !signed ? 'bad_signature' : 'bad_payload', event: valid ? event : null },
}];

// Convex retries until it gets a 2xx, so an event can arrive twice if a
// response is lost. Static data remembers handled event ids for 7 days.
const handled = $getWorkflowStaticData('global').handled ?? {};
const { event } = $input.first().json;
return [{ json: { event, duplicate: Boolean(handled[event.eventId]) } }];

// Only fields Convex sent are used: recipient first name and email, the other
// person's first name, the tool name and dates.
const e = $input.first().json.event;
const day = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const dates = e.loan.startDate === e.loan.endDate ? day(e.loan.startDate) : `${day(e.loan.startDate)} to ${day(e.loan.endDate)}`;
const tool = e.tool.name;
const other = e.counterpart.firstName;
let subject;
let lines;
switch (`${e.loan.status}:${e.recipient.role}`) {
  case 'requested:lender':
    subject = `${other} would like to borrow your ${tool}`;
    lines = [`${other} asked to borrow your ${tool} for ${dates}.`, `Approve or decline it here: ${e.link}`];
    break;
  case 'approved:borrower':
    subject = `${other} approved your request for the ${tool}`;
    lines = [`Good news: ${other} approved your request to borrow the ${tool} for ${dates}.`, `Please return it by ${day(e.loan.endDate)}.`, `Details: ${e.link}`];
    break;
  case 'declined:borrower':
    subject = `Your request for the ${tool} wasn't approved`;
    lines = [
      e.loan.closedReason === 'dates_taken'
        ? `Another request for the ${tool} on overlapping dates (${dates}) was approved first.`
        : `${other} can't lend the ${tool} for ${dates} this time.`,
      `Your requests: ${e.link}`,
    ];
    break;
  case 'cancelled:lender':
    subject = `${other} cancelled their request for your ${tool}`;
    lines = [`${other} no longer needs your ${tool} for ${dates}. Nothing to do.`];
    break;
  case 'cancelled:borrower':
    subject = `The ${tool} is no longer listed`;
    lines = [`The ${tool} you asked to borrow for ${dates} was removed from LendLoop, so your request was cancelled.`, `Your requests: ${e.link}`];
    break;
  case 'returned:borrower':
    subject = `Thanks for returning the ${tool}`;
    lines = [`${other} marked the ${tool} as returned. Thanks for being a good neighbor!`];
    break;
  default:
    subject = `An update on the ${tool}`;
    lines = [`Your loan of the ${tool} is now ${e.loan.status}.`, e.link];
}
const text = [`Hi ${e.recipient.firstName},`, '', ...lines, '', 'LendLoop'].join('\n');
return [{ json: { eventId: e.eventId, to: e.recipient.email, subject, text } }];

// Record the event only after the email went out; static data is saved when
// this production execution ends. Entries older than 7 days are dropped.
const store = $getWorkflowStaticData('global');
const week = 7 * 24 * 60 * 60 * 1000;
const now = Date.now();
store.handled = Object.fromEntries(Object.entries(store.handled ?? {}).filter(([, at]) => now - at < week));
const { eventId } = $('Compose email').first().json;
store.handled[eventId] = now;
return [{ json: { ok: true, eventId } }];
